from collections import deque

def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
    G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G

G = load()

# Compute min distance from each cell to any 2, using only 3s as pathways
def compute_distances(grid):
    h, w = len(grid), len(grid[0])
    dist = [[float('inf')] * w for _ in range(h)]

    # Start BFS from all 2s
    queue = deque()
    for i in range(h):
        for j in range(w):
            if grid[i][j] == 2:
                dist[i][j] = 0
                queue.append((i, j))

    while queue:
        i, j = queue.popleft()
        for di, dj in [(-1,0),(1,0),(0,-1),(0,1)]:  # 4-way for distance computation
            ni, nj = i + di, j + dj
            if 0 <= ni < h and 0 <= nj < w:
                # Can only travel through 3s
                if grid[ni][nj] == 3 and dist[ni][nj] == float('inf'):
                    dist[ni][nj] = dist[i][j] + 1
                    queue.append((ni, nj))

    return dist

demo_input = G['Demo pair 1 input']
demo_output = G['Demo pair 1 output']

dist = compute_distances(demo_input)

print("Checking distance hypothesis...")
for i in range(len(demo_output)):
    for j in range(len(demo_output[0])):
