# Then for each component, if it contains any 2, fill ALL its members with 1
# Additionally, any 0 cell within distance 1 of such a filled region also becomes 1

from collections import deque

def solve_v3(grid):
    h, w = len(grid), len(grid[0])
    result = [[0]*w for _ in range(h)]

    # BFS from all 2s through 3s and 0s
    visited = set()
    queue = deque()

    # Start from all 2s
    for i in range(h):
        for j in range(w):
            if grid[i][j] == 2:
                queue.append((i,j))
                visited.add((i,j))

    # BFS through adjacent cells (including diagonally)
    while queue:
        i, j = queue.popleft()
        for di in [-1, 0, 1]:
            for dj in [-1, 0, 1]:
                if di == 0 and dj == 0: continue
                ni, nj = i+di, j+dj
                if 0 <= ni < h and 0 <= nj < w and (ni,nj) not in visited:
                    visited.add((ni,nj))
                    queue.append((ni,nj))

    # Now mark the result: only cells that were originally 2 or 3 become 1
    # Cells that were 0 never change
    for i in range(h):
        for j in range(w):
            if grid[i][j] in (2, 3) and (i,j) in visited:
                result[i][j] = 1

    return result

