                comp = []
                queue = deque([(i,j)])
                visited_local = {(i,j)}

                while queue:
                    ci, cj = queue.popleft()
                    comp.append((ci,cj))

                    for di, dj in [(0,1), (0,-1), (1,0), (-1,0)]:
                        ni, nj = ci + di, cj + dj
                        if 0 <= ni < h and 0 <= nj < w and (ni,nj) not in visited_local:
                            if grid[ni][nj] in (0, 3):
                                visited_local.add((ni,nj))
                                queue.append((ni,nj))

                visited_global.update(comp)
                components[(i,j)] = comp

